{
  "id": 70,
  "knowledge": "TEI quartile",
  "description": "Categorizes accounts into four groups based on their TEI values.",
  "definition": "Q_{TEI} = \begin{cases} 1 & \text{if TEI} in [0, P_{25}] \\ 2 & \text{if TEI} in (P_{25}, P_{50}] \\ 3 & \text{if TEI} in (P_{50}, P_{75}] \\ 4 & \text{if TEI} in (P_{75}, P_{100}] \\end{cases} where P_n represents the nth percentile of TEI values"
}

